const cfg = $("Configure notification").first().json,
  fields = $("Get Prompt Fields").first().json.fields,
  pages = $input.all().map((x) => x.json.body);
if (
  !pages.length ||
  pages.some(
    (x) =>
      !Array.isArray(x.payloads) ||
      !Number.isSafeInteger(x.cursor) ||
      typeof x.mightHaveMore !== "boolean",
  )
)
  throw Error("Invalid payload page");
const nextCursor = pages.at(-1).cursor,
  out = [];
for (const p of pages) {
  for (const [i, event] of p.payloads.entries()) {
    if (event.error) throw Error("Airtable webhook needs recreation");
    if (event.actionMetadata?.source !== "client") continue;
    const table = event.changedTablesById?.[cfg.table];
    if (!table) continue;
    const eventKey = cfg.hook + ":" + (p.cursor - p.payloads.length + i);
    if (cfg.hook === cfg.records) {
      for (const rowId of Object.keys(table.changedRecordsById ?? {}))
        out.push({
          json: {
            baseId: cfg.base,
            tableId: cfg.table,
            event_type: "row.updated",
            rowId,
            eventKey,
            nextCursor,
          },
        });
    } else
      for (const fieldId of [
        ...Object.keys(table.createdFieldsById ?? {}),
        ...Object.keys(table.changedFieldsById ?? {}),
      ])
        out.push({
          json: {
            baseId: cfg.base,
            tableId: cfg.table,
            event_type: "field.updated",
            fieldId,
            field: fields.find((x) => x.id === fieldId) ?? {},
            eventKey: eventKey + ":" + fieldId,
            nextCursor,
          },
        });
  }
}
return out.length ? out : [{ json: { event_type: "noop", nextCursor } }];

