const cfg = $("Set Airtable Vars").first().json,
  t = $input
    .all()
    .map((x) => x.json)
    .find((x) => x.id === cfg.tableId),
  field = t?.fields?.find((x) => x.name === cfg.inputField);
if (!field) throw Error("Input field missing");
return [{ json: field, pairedItem: { item: 0 } }];

const base = "YOUR_AIRTABLE_BASE_ID",
  table = "YOUR_AIRTABLE_TABLE_ID",
  records = "YOUR_RECORDS_WEBHOOK_ID",
  fields = "YOUR_FIELDS_WEBHOOK_ID",
  b = $json.body;
if (!b || b.base?.id !== base || ![records, fields].includes(b.webhook?.id))
  throw Error("Unexpected Airtable notification");
const cursors = $getWorkflowStaticData("global");
return [
  {
    json: { base, table, records, fields, hook: b.webhook.id, cursor: cursors[b.webhook.id] ?? 1 },
  },
];

